{
  "title": "Tính bán kính đường tròn thiết diện của hình nón",
  "description": "Bài toán này minh họa cách xác định một thiết diện của hình nón bằng một mặt phẳng vuông góc với trục, và tính bán kính của đường tròn thiết diện đó.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3",
      "at": [0, 0, 0],
      "model_assumption": "Đặt tâm đáy O tại gốc tọa độ (0,0,0)."
    },
    {
      "name": "S",
      "type": "point3",
      "at": [0, 0, 18],
      "source_fact_id": "height_so",
      "model_assumption": "Đặt đỉnh S trên trục Oz, cách O một khoảng bằng chiều cao của nón."
    },
    {
      "name": "A",
      "type": "point3",
      "at": [12, 0, 0],
      "source_fact_id": "base_radius",
      "model_assumption": "Đặt điểm A trên đường tròn đáy để xác định bán kính đáy."
    },
    {
      "name": "cone_S_O_A",
      "type": "solid",
      "source_fact_id": "cone_s_o"
    },
    {
      "name": "T",
      "type": "point3",
      "source_fact_id": "t_on_so"
    },
    {
      "name": "plane_alpha",
      "type": "plane3",
      "source_fact_id": "plane_through_t"
    },
    {
      "name": "c",
      "type": "section",
      "source_fact_id": "intersection_circle_c"
    },
    {
      "name": "r_c",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "construct_curved_solid",
      "target_var": "cone_S_O_A",
      "curved_kind": "cone",
      "anchor": "O",
      "apex_or_top": "S",
      "rim_point": "A",
      "label": "Hình nón có đỉnh S, tâm đáy O, và điểm A trên vành đáy"
    },
    {
      "kind": "construct_line",
      "target_var": "line_SO",
      "through_a": "S",
      "through_b": "O",
      "label": "Trục của hình nón SO"
    },
    {
      "kind": "construct_point",
      "target_var": "T",
      "expr": {
        "kind": "divide_segment",
        "a": "S",
        "b": "O",
        "ratio": "1/3"
      },
      "label": "Điểm T trên đoạn SO với tỉ lệ ST:TO = 1:2"
    },
    {
      "kind": "assign",
      "target_var": "plane_alpha",
      "expr": {
        "kind": "plane_perpendicular_to_line",
        "point": "T",
        "line": "line_SO"
      },
      "label": "Mặt phẳng đi qua T và vuông góc với SO"
    },
    {
      "kind": "construct_section",
      "target_var": "c",
      "solid": "cone_S_O_A",
      "plane": "plane_alpha",
      "label": "Đường tròn (c) là thiết diện của hình nón với mặt phẳng alpha"
    },
    {
      "kind": "assign",
      "target_var": "r_c",
      "expr": {
        "kind": "measure",
        "quantity": "radius",
        "of": "c"
      },
      "label": "Bán kính của đường tròn (c)"
    }
  ],
  "pedagogical_intent": "Bài toán này giúp học sinh hiểu về mối quan hệ tỉ lệ trong hình nón và cách một mặt phẳng cắt vuông góc với trục tạo ra một đường tròn đồng dạng với đáy."
}

